{ arg out=0, freq=440, amp=0.1, gate=1, detune=0.005, pan=0, rvbMix=0.5;
    var sig, env;
    // Long, slow attack and release envelope
    env = EnvGen.ar(
        Env.adsr(2.0, 3.0, 0.7, 5.0, curve: -4),
        gate: gate,
        doneAction: 2
    );

    // Multiple detuned sine waves for a lush sound
    sig = SinOsc.ar(freq);
    sig = sig + SinOsc.ar(freq * (1 + detune));
    sig = sig + SinOsc.ar(freq * (1 - detune));
    sig = sig / 3; // Normalize volume

    // Apply amplitude and envelope
    sig = sig * amp * env;

    // Stereo spread
    sig = Pan2.ar(sig, pan);

    // Add a touch of reverb
    sig = FreeVerb.ar(sig, 0.8, 0.9, 0.5) * rvbMix + sig * (1 - rvbMix);

    Out.ar(out, sig);
}
